  "الهجره باقيه الي ان تقوم الساعه": "الْهِجْرَةُ بَاقِيَةٌ إِلَى أَنْ تَقُومَ السَّاعَةُ.",
  "الهجره فريضه علي هذه الامه": "الْهِجْرَةُ فَرِيضَةٌ عَلَى هَذِهِ الْأُمَّةِ.",
  "اجل واب الهجره فريضه علي هذه االمه من بلد الشرك الي بلد الاسلام وهي باقيه الي ان تقوم الساعه  ما الدليل علي فرضيه الهجره": "الْهِجْرَةُ فَرِيضَةٌ عَلَى هَذِهِ الْأُمَّةِ مِنْ بَلَدِ الشِّرْكِ إِلَى بَلَدِ الْإِسْلَامِ، وَهِيَ بَاقِيَةٌ إِلَى أَنْ تَقُومَ السَّاعَةُ. مَا الدَّلِيلُ عَلَى فَرْضِيَّةِ الْهِجْرَةِ؟",
  "اعظم ما نهي الله عنه هو": "أَعْظَمُ مَا نَهَى اللَّهُ عَنْهُ هُوَ:",
  "الغيبه": "الْغِيبَةُ",
  "اعظم ما نهي الله عنه الشرك": "أَعْظَمُ مَا نَهَى اللَّهُ عَنْهُ الشِّرْكُ.",
  "كم انواع الشرك": "كَمْ أَنْوَاعُ الشِّرْكِ؟",
  "اثنان اكبر واصغر": "اثْنَانِ: أَكْبَرُ وَأَصْغَرُ",
  "الشرك الاكبر والشرك الاصغر": "الشِّرْكُ الْأَكْبَرُ وَالشِّرْكُ الْأَصْغَرُ.",
  "وهو دعوه غير هم عه كم انواع الشرك": "وَهُوَ دَعْوَةُ غَيْرِ هُمْ عِهِ كَمْ أَنْوَاعُ الشِّرْكِ",
  "المؤلف ولد في مكه": "الْمُؤَلِّفُ وُلِدَ فِي مَكَّةَ.",
  "ولد في بلده العيينه": "وُلِدَ فِي بَلْدَةِ الْعُيَيْنَةِ.",
  "الاصول الثلاثه سميت بذلك لانها تشرح اصول الفقه": "الْأُصُولُ الثَّلَاثَةُ سُمِّيَتْ بِذَلِكَ لِأَنَّهَا تَشْرَحُ أُصُولَ الْفِقْهِ.",
  "بل لانها تجيب عن اسئله القبر الثلاثه": "بَلْ لِأَنَّهَا تُجِيبُ عَنْ أَسْئِلَةِ الْقَبْرِ الثَّلَاثَةِ.",
  "العلم قبل العمل واجب": "الْعِلْمُ قَبْلَ الْعَمَلِ وَاجِبٌ.",
  "بدا الله بالعلم قبل القول والعمل": "بَدَأَ اللَّهُ بِالْعِلْمِ قَبْلَ الْقَوْلِ وَالْعَمَلِ.",
  "تعرف ربك باياته ومخلوقاته": "تَعْرِفُ رَبَّكَ بِآيَاتِهِ وَمَخْلُوقَاتِهِ.",
  "الليل والنهار والشمس والقمر من اياته": "اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ مِنْ آيَاتِهِ.",
  "الخوف والرَجَاءَ والتوكل عبادات قلبيه": "الْخَوْفُ وَالرَّجَاءُ وَالتَّوَكُّلُ عِبَادَاتٌ قَلْبِيَّةٌ.",
  "وهي من انواع العباده التي امر الله بها": "وَهِيَ مِنْ أَنْوَاعِ الْعِبَادَةِ الَّتِي أَمَرَ اللَّهُ بِهَا.",
  "يجوز النذر لغير الله اذا كان للصالحين": "يَجُوزُ النَّذْرُ لِغَيْرِ اللَّهِ إِذَا كَانَ لِلصَّالِحِينَ.",
  "النبي ﷺ عاش 63 سنه": "النَّبِيُّ ﷺ عَاشَ 63 سَنَةً.",
  "ثلاث وستون سنه": "ثَلَاثٌ وَسِتُّونَ سَنَةً.",
  "الهجره هي السفر للسياحه": "الْهِجْرَةُ هِيَ السَّفَرُ لِلسِّيَاحَةِ.",
  "بل الانتقال من بلد الشرك الي بلد الاسلام": "بَلِ الِانْتِقَالُ مِنْ بَلَدِ الشِّرْكِ إِلَى بَلَدِ الْإِسْلَامِ.",
  "الشرك الذي يحبط جميع الاعمال ويخلد صاحبه في النار هو": "الشِّرْكُ الَّذِي يُحْبِطُ جَمِيعَ الْأَعْمَالِ وَيُخَلِّدُ صَاحِبَهُ فِي النَّارِ هُوَ:",
  "الشرك الاكبر": "الشِّرْكُ الْأَكْبَرُ",
