  "كن في الدنيا كانك غريب يحث علي": "\"كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ\" يَحُثُّ عَلَى:",
  "قصر الامل والاستعداد للاخره": "قِصَرِ الْأَمَلِ وَالِاسْتِعْدَادِ لِلْآخِرَةِ",
  "جمع المال": "جَمْعِ الْمَالِ",
  "طول الامل": "طُولِ الْأَمَلِ",
  "قصر الامل والاستعداد للاخره هي الاجابه المطابقه لما ورد في النص والمعني المراد": "قِصَرُ الْأَمَلِ وَالِاسْتِعْدَادِ لِلْآخِرَةِ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِمَا وَرَدَ فِي النَّصِّ وَالْمَعْنَى الْمُرَادُ.",
  "معني تحقيق التوحيد": "مَعْنَى \"تَحْقِيقِ التَّوْحِيدِ\":",
  "تصفيته من الشرك والبدع والمعاصي": "تَصْفِيَتِهِ مِنَ الشِّرْكِ وَالْبِدَعِ وَالْمَعَاصِي",
  "حفظه فقط": "حِفْظِهِ فَقَطْ",
  "تعلمه فقط": "تَعَلُّمِهِ فَقَطْ",
  "تعليمه": "تَعْلِيمِهِ",
  "تصفيته من الشرك والبدع والمعاصي هو المعني الصحيح المذكور في شرح الكتاب لهذه الكلمه/المصطلح": "تَصْفِيَتِهِ مِنْ الشِّرْكِ وَالْبِدَعِ وَالْمَعَاصِي» هُوَ الْمَعْنَى الصَّحِيحُ الْمَذْكُورُ فِي شَرْحِ الْكِتَابِ لِهَذِهِ الْكَلِمَةِ/الْمُصْطَلَحِ.",
  "معني العباده في اللغه هو": "مَعْنَى \"الْعِبَادَةِ\" فِي اللُّغَةِ هُوَ:",
  "التذلل والخضوع": "التَّذَلُّلُ وَالْخُضُوعُ",
  "الصلاه خاصه": "الصَّلَاةُ خَاصَّةً",
  "الطواف": "الطَّوَافُ",
  "التذلل والخضوع هو المعني الصحيح المذكور في شرح الكتاب لهذه الكلمه/المصطلح": "التَّذَلُّلُ وَالْخُضُوعُ» هُوَ الْمَعْنَى الصَّحِيحُ الْمَذْكُورُ فِي شَرْحِ الْكِتَابِ لِهَذِهِ الْكَلِمَةِ/الْمُصْطَلَحِ.",
  "يخلطوا": "يَخْلِطُوا",
