  "الترتيب والتراخي هي الاجابه المطابقه لما ورد في النص والمعني المراد": "التَّرْتِيبَ وَالتَّرَاخِيَ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "عظمه الله هي الاجابه المطابقه لما ورد في النص والمعني المراد": "عَظَمَةِ اللَّهِ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "تمحق البركه هي الاجابه المطابقه لما ورد في النص والمعني المراد": "تَمْحَقُ الْبَرَكَةِ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "استهان باسم الله هي الاجابه المطابقه لما ورد في النص والمعني المراد": "اسْتَهَانَ بِاسْمِ اللَّهُ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "وسائل الشرك هي الاجابه المطابقه لما ورد في النص والمعني المراد": "وَسَائِلِ الشِّرْكِ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "عباده اصحابها هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "عِبَادَةٌ أَصْحَابِهَا» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "نصيب من الملك هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "نَصِيبٍ مِنْ الْمُلْكِ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "اذن له الرب هي الاجابه المطابقه لما ورد في النص والمعني المراد": "أذِن لَهُ الربّ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "لله وحده هي الاجابه المطابقه لما ورد في النص والمعني المراد": "لِلَّهِ وَحْدَهُ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "اذنه هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "إِذْنِهِ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "الفزع والخوف عند سماع الوحي هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "الْفَزَعُ وَالْخَوْفُ عِنْدَ سَمَاعِ الْوَحْيِ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "غشيه وخوف هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "غَشْيَةٌ وَخَوْفٌ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "الذات والقدر والقهر هي الاجابه المطابقه لما ورد في النص والمعني المراد": "الذَّاتِ وَالْقَدْرِ وَالْقَهْرِ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "تعظيم الملائكه لكلامه هو الموضع الصحيح الذي استدل به المؤلف في هذا الموطن": "تَعْظِيمُ الْمَلَائِكَةُ لِكَلَامِهِ» هُوَ الموضع الصَّحِيحُ الَّذِي استدلّ بِهِ المؤلّف فِي هَذَا الموطن.",
  "الملائكه والانبياء والصالحين هي الاجابه المطابقه لما ورد في النص والمعني المراد": "الْمَلَائِكَةُ وَالْأَنْبِيَاءَ وَالصَّالِحِينَ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "في الحديث القدسي يؤذيني ابن ادم يسب": "فِي الْحَدِيثِ الْقُدْسِيِّ: \"يُؤْذِينِي ابْنُ آدَمَ يسبّ\":",
  "الدهر هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "الدَّهْرِ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
  "النهار هي الاجابه المطابقه لما ورد في النص والمعني المراد": "النَّهَارُ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "شرك هي الاجابه المطابقه لما ورد في النص والمعني المراد": "شِرْكٌ» هِيَ الْإِجَابَةُ الْمُطَابِقَةُ لِما وَرَدَ فِي النصّ وَالْمَعْنَى الْمُرَادُ.",
  "مدبر الامور وهو الله هو ما ثبت في لفظ الحديث/الاثر كما اورده الكتاب": "مدبّر الْأُمُورِ وَهُوَ اللَّهُ» هُوَ مَا ثَبَتَ فِي لَفْظِ الْحَدِيثِ/الْأَثَرِ كَمَا أَوْرَدَهُ الْكِتَابِ.",
